// #WCCChallenge
// Upside-down

let grass = [];
let stem = [];
let bees = [];

function setup() {
  createCanvas(800, 800);

  for (let i = 0; i < 200; i++) {
    grass.push(new Grass());
  }

  for (let i = 0; i < 15; i++) {
    stem.push(new Stem());
    bees.push(new Bee());
  }
}

function draw() {
  background(10);

  stem.forEach((s) => {
    s.updateStem();
    s.drawStem();
    s.flower();
  });

  grass.forEach((g) => {
    g.updateGrass();
    g.drawGrass();
  });

  bees.forEach((b) => {
    b.updateBee();
    b.drawBee();
  });
}

class Grass {
  constructor() {
    this.x1 = random(10, width - 10);
    this.x2off = random(0, 5);
    this.y1 = 0;
    this.y2 = random(height * 0.1, height * 0.3);
  }

  updateGrass() {
    this.x2off += 0.005;
    this.x2 = map(noise(this.x2off), 0, 1, this.x1 - 50, this.x1 + 50);
  }

  drawGrass() {
    stroke(100, 200, 10, 50);
    strokeWeight(3);
    line(this.x1, this.y1, this.x2, this.y2);
  }
}

class Stem {
  constructor() {
    this.x1 = random(100, width - 100);
    this.x2off = random(0, 5);
    this.y1 = 0;
    this.y2 = random(height * 0.5, height * 0.8);
    this.vary = random(1, 3);
  }

  updateStem() {
    this.x2off += 0.005;
    this.x2 = map(noise(this.x2off), 0, 1, this.x1 - 50, this.x1 + 50);
  }

  drawStem() {
    stroke(250, 204, 21, 100);
    strokeWeight(0.5 * this.vary);
    line(this.x1, this.y1, this.x2, this.y2);
  }

  flower() {
    push();
    strokeWeight(1);
    stroke(30);
    fill(14, 165, 233);
    translate(this.x2, this.y2);
    for (let i = 0; i < 5; i++) {
      ellipse(0, 0, 5 * this.vary, 30 * this.vary);
      rotate(PI / 5);
    }
    fill(239, 68, 68);
    circle(0, 0, 10 * this.vary);
    pop();
  }
}

class Bee {
  constructor() {
    this.xOff = random(0, 500);
    this.yOff = random(500, 1000);
    this.sizeOff = random(100, 200);
  }

  updateBee() {
    this.xOff += 0.005;
    this.yOff += 0.005;
    this.sizeOff += 0.005;

    this.x = map(noise(this.xOff), 0, 1, 0, width);
    this.y = map(noise(this.yOff), 0, 1, height * 0.3, height);
    this.size = map(noise(this.sizeOff), 0, 1, 0, 12);
  }

  drawBee() {
    fill(200, 200, 0);
    noStroke();
    circle(this.x, this.y, this.size);
  }
}


